SELECT a FROM t ORDER BY a FOR UPDATE SKIP LOCKED LIMIT 10;

SELECT a FROM t FOR SHARE NOWAIT LIMIT 1 OFFSET 2;

SELECT a FROM t WHERE b = 1 FOR UPDATE LIMIT 1;

SELECT a FROM t ORDER BY a LIMIT 10 FOR UPDATE SKIP LOCKED;

WITH c AS (
    SELECT a FROM t
    ORDER BY a
    FOR UPDATE SKIP LOCKED
    LIMIT 10
)

UPDATE t SET b = now()
FROM c
WHERE t.a = c.a
RETURNING t.a;
